import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { supabase } from '../lib/supabase';

const AuthContext = createContext();

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [staff, setStaff] = useState(null);
  const [loading, setLoading] = useState(true);
  const [activeStoreId, setActiveStoreId] = useState(null);
  const [availableStores, setAvailableStores] = useState([]);
  const [subscriptionStatus, setSubscriptionStatus] = useState(null);
  const [trialDaysLeft, setTrialDaysLeft] = useState(null);
  const [isLocked, setIsLocked] = useState(false);

  // Load user from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('local_user');
    if (saved) {
      const parsed = JSON.parse(saved);
      setUser(parsed);
      loadUserData(parsed);
    } else {
      setLoading(false);
    }
  }, []);

  const loadUserData = async (authUser) => {
    try {
      // Get all stores (from local storage)
      const stores = JSON.parse(localStorage.getItem('bwanali_stores') || '[]');
      setAvailableStores(stores);

      if (stores.length === 0) {
        setStaff(null);
        setLoading(false);
        return;
      }

      const activeId = activeStoreId || stores[0].id;
      setActiveStoreId(activeId);

      // Get staff info
      const staffList = JSON.parse(localStorage.getItem('bwanali_staff') || '[]');
      const staffMember = staffList.find(s => s.email === authUser.email) || {
        full_name: authUser.email || 'User',
        email: authUser.email,
        role: 'admin',
        is_active: true,
        store: stores[0]
      };
      setStaff(staffMember);

      // Subscription status
      const store = stores.find(s => s.id === activeId) || stores[0];
      setSubscriptionStatus(store.subscription_status || 'trialing');
      setIsLocked(store.locked || false);

      if (store.trial_started_at) {
        const end = new Date(store.trial_started_at);
        end.setDate(end.getDate() + 3);
        const left = Math.max(0, Math.ceil((end - new Date()) / 86400000));
        setTrialDaysLeft(left);
        if (left === 0) {
          const updatedStores = stores.map(s => s.id === activeId ? { ...s, subscription_status: 'expired', locked: true } : s);
          localStorage.setItem('bwanali_stores', JSON.stringify(updatedStores));
          setSubscriptionStatus('expired');
          setIsLocked(true);
        }
      }
    } catch (e) {
      console.error('Failed to load user data', e);
    } finally {
      setLoading(false);
    }
  };

  const checkSubscription = useCallback(async (storeId) => {
    const stores = JSON.parse(localStorage.getItem('bwanali_stores') || '[]');
    const store = stores.find(s => s.id === storeId);
    if (store) {
      setSubscriptionStatus(store.subscription_status);
      setIsLocked(store.locked || false);
    }
  }, []);

  const signIn = async (email, password) => {
    const { data, error } = await supabase.auth.signInWithPassword({ email, password });
    if (error) return { error };
    setUser(data.user);
    loadUserData(data.user);
    return {};
  };

  const signOut = async () => {
    await supabase.auth.signOut();
    setUser(null);
    setStaff(null);
    setActiveStoreId(null);
    setAvailableStores([]);
  };

  const hasActive = subscriptionStatus === 'active' || (subscriptionStatus === 'trialing' && !isLocked);

  return (
    <AuthContext.Provider
      value={{
        user, staff, setStaff, storeId: activeStoreId, availableStores,
        switchStore: (id) => { setActiveStoreId(id); loadUserData(user); },
        signIn, signOut, loading,
        isAdmin: staff?.role === 'admin',
        isManager: staff?.role === 'manager' || staff?.role === 'admin',
        canManageInventory: true,
        canDelete: staff?.role === 'admin',
        subscriptionStatus, trialDaysLeft,
        hasActiveSubscription: hasActive,
        isLocked, checkSubscription,
        reloadStaff: () => loadUserData(user),
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => useContext(AuthContext);
